using System;using System.IO;using System.Linq;using System.Collections.Generic;using System.Reflection;using Cysharp.Threading.Tasks;using UnityEngine;using UnityEditor;using UnityEngine.SceneManagement;using UnityEngine.InputSystem;using UnityEngine.InputSystem.LowLevel;using UnityEngine.EventSystems;using UnityEngine.Events;using PaperPixelGames.Core.Managers;using PaperPixelGames.Core.Tablet;using PaperPixelGames.Framework.Patterns;using SushiAndFish.Casino;using SushiAndFish.Casino.Original;using SushiAndFish.Casino.Original.CasinoLab;using SushiAndFish.Casino.Original.Extensions;using Object=UnityEngine.Object;
public static partial class CityExpansionPlayAudit {
 [Serializable]public class InputCase{public string path,method,before,after,hover,error;public bool reached,invoked,correct;public Vector3 eye,target;public List<string> hits=new List<string>();}
 [Serializable]public class InputReceipt{public string utc,error,stage;public bool passed,ready;public long coins;public List<InputGameCase> games=new List<InputGameCase>();public List<InputCase> buttons=new List<InputCase>();public List<string> diagnosis=new List<string>();}
 static InputReceipt detailed;static string DetailedPath=>Path.Combine(Reports,SessionState.GetBool(Key+"screenshot",false)?"screenshot-followup-input.json":SessionState.GetBool(Key+"crapsOnly",false)?"casino-final-followup-input.json":"casino-detailed-input-audit.json");
 public static void DetailedInput(){SessionState.SetBool(Key+"fullInput",false);SessionState.SetBool(Key+"detailed",true);SessionState.SetBool(Key+"roofCoast",false);SessionState.SetBool(Key+"probe",false);StartMode(false);}
 static string FullPath(Transform t){var s=t.name;while(t.parent){t=t.parent;s=t.name+"/"+s;}return s;}
 static void DetailedStage(string s){detailed.stage=s;File.WriteAllText(DetailedPath,JsonUtility.ToJson(detailed,true));Stage("INPUT_"+s);}
 static string Methods(InteractableEventTrigger b)=>string.Join(";",Enumerable.Range(0,b.serverOnInteractEvent.GetPersistentEventCount()).Select(i=>b.serverOnInteractEvent.GetPersistentMethodName(i)));
 static string ButtonState(InteractableBase b){if(b is DragonTowerButton d)return d.buttonState.ToString();if(b is KenoButton k)return CasinoLabBootstrap.Field<bool>(k,"_isSelected").ToString();if(b is RouletteButton r)return string.Join(";",CasinoLabBootstrap.Field<Dictionary<string,long>>(r.GetComponentInParent<Roulette>(),"_bets").Select(x=>x.Key+"="+x.Value));if(b is MoneyWheelButton w)return CasinoLabBootstrap.Field<string>(w.GetComponentInParent<MoneyWheel>(),"_currentBettingOption");return "";}
 static async UniTask<InputCase> PressActual(ParkCasinoIntegration c,InteractableBase b,bool click=false){
  var q=new InputCase{path=FullPath(b.transform),method=b is InteractableEventTrigger e?Methods(e):b.GetType().Name};detailed.buttons.Add(q);var co=b.GetComponents<Collider>().FirstOrDefault(x=>x.enabled);q.target=co?co.bounds.center:b.transform.position;await Aim(c,q.target);await Pause(.15f);if(b is Dice){for(int attempt=0;attempt<4&&c.LogicInteractor.TargetInteractable!=b;attempt++){if(co)q.target=co.bounds.center;await Aim(c,q.target);await Pause(.12f);}}q.eye=CasinoRuntimeContext.PlayerCamera.transform.position;q.hover=c.LogicInteractor.TargetInteractable is Component comp?FullPath(comp.transform):c.LogicInteractor.TargetInteractable?.GetType().Name;q.reached=c.LogicInteractor.TargetInteractable==b;
  q.hits=Physics.SphereCastAll(new Ray(q.eye,CasinoRuntimeContext.PlayerCamera.transform.forward),c.LogicInteractor.raycastRadius,c.LogicInteractor.raycastDistance,c.LogicInteractor.raycastLayer,QueryTriggerInteraction.Collide).OrderBy(h=>h.distance).Take(15).Select(h=>FullPath(h.transform)+" @"+h.distance+" trigger="+h.collider.isTrigger).ToList();
  var stateBefore=ButtonState(b);int pressBefore=c.PressCount;int calls=0;UnityAction<PlayerInteract> listener=_=>calls++;if(b is InteractableEventTrigger be)be.serverOnInteractEvent.AddListener(listener);
  if(q.reached){if(click){InputSystem.QueueStateEvent(mouse,new MouseState{buttons=1});await Pause(.10f);InputSystem.QueueStateEvent(mouse,new MouseState());await Pause(.20f);}else await KeyE();}
  if(b is InteractableEventTrigger bt)bt.serverOnInteractEvent.RemoveListener(listener);q.invoked=calls>0;if(!(b is InteractableEventTrigger))q.invoked=ButtonState(b)!=stateBefore || (b is MoneyWheelButton mw && CasinoLabBootstrap.Field<string>(mw.GetComponentInParent<MoneyWheel>(),"_currentBettingOption")==mw.betOption && c.PressCount>pressBefore);q.correct=q.reached&&q.invoked;if(b is Dice)q.error="layer="+b.gameObject.layer+" interactable="+b.IsInteractable+" active="+b.gameObject.activeInHierarchy+" colliders="+string.Join(";",b.GetComponentsInChildren<Collider>(true).Select(x=>x.name+" enabled="+x.enabled+" active="+x.gameObject.activeInHierarchy+" bounds="+x.bounds));return q;
 }
 static async UniTask DetailedRun(ParkCasinoIntegration c){detailed=new InputReceipt{utc=DateTime.UtcNow.ToString("o"),ready=true};try{
  DetailedStage("SHORE_RAYS");foreach(var p in new[]{new Vector3(-157,15,-30),new Vector3(-10.9f,15,27),new Vector3(.78f,15,27),new Vector3(-180,15,-30)})foreach(var h in Physics.RaycastAll(p,Vector3.down,100,~0,QueryTriggerInteraction.Ignore).OrderBy(h=>h.distance))detailed.diagnosis.Add("SUPPORT "+p+" -> "+FullPath(h.transform)+" point="+h.point+" enabled="+h.collider.enabled+" mesh="+(h.collider is MeshCollider mc&&mc.sharedMesh?mc.sharedMesh.name:""));
  DetailedStage("TABLET");c.HostPlayer.TeleportPlayer(new Vector3(66,3.1f,-13),true);c.HostPlayer.FirstPersonCharacter.SetVelocity(Vector3.zero);InputSystem.QueueStateEvent(keyboard,new KeyboardState(UnityEngine.InputSystem.Key.Tab));await Pause(.12f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());await Pause(1);var tab=c.HostPlayer.GetComponentInChildren<TabletController>(true);var button=CityExpansionInspection.Field<PaperPixelGames.Framework.UI.BaseButton>(tab,"_mapAppButton");var rect=button.GetComponent<RectTransform>();var canvas=button.GetComponentInParent<Canvas>();var screen=RectTransformUtility.WorldToScreenPoint(canvas.worldCamera,rect.TransformPoint(rect.rect.center));detailed.diagnosis.Add("UI screen="+screen+" dims="+Screen.width+","+Screen.height+" cam="+canvas.worldCamera.name+" rect="+canvas.worldCamera.pixelRect+" rt="+(canvas.worldCamera.targetTexture?canvas.worldCamera.targetTexture.name:"none")+" active="+tab.IsTabletActive);
  foreach(var m in Object.FindObjectsByType<UnityEngine.EventSystems.BaseInputModule>(FindObjectsInactive.Include,FindObjectsSortMode.None))detailed.diagnosis.Add("MODULE "+FullPath(m.transform)+" active="+m.isActiveAndEnabled+" type="+m.GetType().FullName);
  var ped=new PointerEventData(EventSystem.current){position=screen};var hits=new List<RaycastResult>();EventSystem.current.RaycastAll(ped,hits);foreach(var h in hits.Take(20))detailed.diagnosis.Add("UIHIT "+FullPath(h.gameObject.transform)+" module="+h.module.GetType().Name+" distance="+h.distance);
  InputSystem.QueueStateEvent(mouse,new MouseState{position=screen});await Pause(.12f);InputSystem.QueueStateEvent(mouse,new MouseState{position=screen,buttons=1});await Pause(.12f);InputSystem.QueueStateEvent(mouse,new MouseState{position=screen});await Pause(.4f);detailed.diagnosis.Add("UI clicked="+(CityExpansionInspection.Field<object>(tab,"_currentActiveApp") is MapApp));InputSystem.QueueStateEvent(keyboard,new KeyboardState(UnityEngine.InputSystem.Key.Escape));await Pause(.12f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());await Pause(.7f);
  if(tab.IsTabletActive){InputSystem.QueueStateEvent(keyboard,new KeyboardState(UnityEngine.InputSystem.Key.Escape));await Pause(.12f);InputSystem.QueueStateEvent(keyboard,new KeyboardState());await Pause(.7f);}detailed.diagnosis.Add("UI closed="+!tab.IsTabletActive);
  c.HostEconomy.SetSavedGoldBalance(0,"10000000000",c.HostEconomy.ScrapBalance.Value);detailed.coins=c.WholeCoins;
  if(SessionState.GetBool(Key+"fullInput",false)){await FullInputRounds(c);detailed.passed=detailed.games.Count==16&&detailed.games.All(g=>string.IsNullOrEmpty(g.error)&&g.started&&g.finished&&g.result&&g.wallet&&g.grounded)&&detailed.buttons.All(b=>b.correct);DetailedStage(detailed.passed?"PASS":"FAILED");return;}
  DetailedStage("BLACKJACK");var elevator=NetworkSingleton<ElevatorManager>.Instance;c.HostPlayer.TeleportPlayer(elevator.playerSpawnPosition.position-Vector3.up*(.4f*c.CurrentScale),true);await Pause(.25f);CasinoLabBootstrap.Field<List<Transform>>(elevator,"buttonList")[4].GetComponent<InteractableEventTrigger>().ServerOnInteract(c.LogicInteractor);await Wait(()=>!elevator.isTeleporting&&c.CurrentFloor==4,35);await Pause(.3f);SceneManager.SetActiveScene(c.ModuleRoot.gameObject.scene);bool replaced=false;c.Bootstrap.StartCoroutine(ReplaceDetailed(0,()=>replaced=true));await Wait(()=>replaced,35);SceneManager.SetActiveScene(c.gameObject.scene);var game=CasinoLabSelection.SelectedGame;var cluster=(GameObject)typeof(CasinoLabSelection).GetField("currentCluster",BindingFlags.Static|BindingFlags.NonPublic).GetValue(null);var point=game.Keypad.transform;var outward=point.position-cluster.transform.position;outward.y=0;if(outward.sqrMagnitude<.1f)outward=-point.forward;outward.Normalize();var front=point.forward;front.y=0;front.Normalize();var stand=point.position+front*1.65f;stand.y=c.nativeMapOrigin.y+.3f;c.HostPlayer.TeleportPlayer(stand,true);c.HostPlayer.FirstPersonCharacter.SetVelocity(Vector3.zero);await Pause(.4f);c.RegisterCasinoButtons();
  foreach(var b in game.Keypad.GetComponentsInChildren<InteractableEventTrigger>(true)){var before=game.Keypad.Network_currentInput;var q=await PressActual(c,b);q.before=before;q.after=game.Keypad.Network_currentInput;q.error=game.Keypad.Network_errorMessage;DetailedStage("KEYPAD_"+b.name);}
  foreach(var b in game.GetComponentsInChildren<InteractableEventTrigger>(true).Where(b=>!b.GetComponentInParent<Keypad>())){detailed.diagnosis.Add("GAME BUTTON "+FullPath(b.transform)+" METHODS "+Methods(b)+" active="+b.gameObject.activeInHierarchy+" interactable="+b.IsInteractable+" meets="+b.MeetRequirements);}
  detailed.passed=detailed.buttons.Count>0&&detailed.buttons.All(x=>x.correct);DetailedStage(detailed.passed?"PASS":"FAILED");
 }catch(Exception ex){detailed.error=ex.ToString();DetailedStage("FAILED");}}
 static System.Collections.IEnumerator ReplaceDetailed(int i,Action done){yield return CasinoLabSelection.ReplaceCluster(i);done();}
}
